def q(num, section, text, a, b, c, d, ans, exp, track="common", diff="Medium"):
    """Helper to build a standardized question record."""
    if track == "non_muslim":
        qid = f"spsc_cce26_nm_{num}"
        display_no = f"{num} (Alt)"
    else:
        qid = f"spsc_cce26_q_{num}"
        display_no = f"{num:02d}" if num < 100 else str(num)
    return {
        "_id": qid,
        "qNo": num,
        "displayNo": display_no,
        "track": track,  # 'common', 'muslim', or 'non_muslim'
        "section": section,
        "subCategory": section,
        "category": {
            "_id": "cat_spsc_cce_2026",
            "name": "SPSC CCE Screening Test 2026"
        },
        "questionText": text,
        "options": {"A": a, "B": b, "C": c, "D": d},
        "correctAnswer": ans,
        "explanation": exp,
        "difficulty": diff
    }

